using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: The default discriminator property was renamed
        // from "Discriminator" to "$type". Existing documents still store "Discriminator",
        // so we must explicitly configure the old name to avoid query mismatches.
        modelBuilder.Entity<Product>().HasDiscriminant<string>("Discriminator");
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

using Microsoft.EntityFrameworkCore;

class CosmosQueryService
{
    // EF Core 9 breaking change: Synchronous I/O on the Cosmos DB provider
    // now throws InvalidOperationException. All queries must use async methods.

    // BEFORE (broken in EF Core 9):
    //   var products = db.Products.ToList();
    //   var product  = db.Products.First(p => p.Name == name);
    //   var count    = db.Products.Count();

    // AFTER (required fix – use async equivalents):
    async Task<List<Product>> GetAllProductsAsync(CosmosDbContext db)
    {
        return await db.Products.ToListAsync();
    }

    async Task<Product> GetProductByNameAsync(CosmosDbContext db, string name)
    {
        return await db.Products.FirstAsync(p => p.Name == name);
    }

    async Task<int> GetProductCountAsync(CosmosDbContext db)
    {
        return await db.Products.CountAsync();
    }
}

